155	function HeaderNavAutoDetect(props: { tabs: HeaderNavTabItem[] }) {
156	  const activeTabId = useAutoActiveTabId(props.tabs);
157	  return <HeaderNavInner tabs={props.tabs} activeTabId={activeTabId} />;
158	}
