20	/**
21	 * Resolves an href for rendering. External URLs are returned unchanged;
22	 * internal paths are resolved through react-router's useHref so they
23	 * respect the current basename and route context.
24	 *
25	 * @internal
26	 */
27	export function useResolvedHref(href: string): string;
28	export function useResolvedHref(href: string | undefined): string | undefined;
29	export function useResolvedHref(href: string | undefined): string | undefined {
30	  const hasRouter = useInRouterContext();
31	  // useHref throws outside a Router, so we guard with useInRouterContext.
32	  // The guard is safe because a component's router context does not
33	  // change during its lifetime, keeping the hook call count stable.
34	  if (!hasRouter) {
35	    return href;
36	  }
37	  const resolved = useHref(href ?? '');
38	  if (!href || isExternalLink(href)) {
39	    return href;
40	  }
41	  return resolved;
42	}
